const void *curkey, *curdata;
    size_t bucket = argbucket;
    size_t nentries = CKH_ENTRIES;
    size_t max_iterations = nentries * 2; // or some other limit

    for (size_t i = 0; i < max_iterations; i++) {
        // Try to insert into the current bucket
        if (ckh_evict(ckh, bucket, argkey, argdata, &curkey, &curdata)) {
            // Insertion succeeded
            return false;
        }

        // Eviction happened, curkey/curdata now holds the evicted item
        // Find the alternate bucket for the evicted item
        size_t alt_bucket = ckh_hash(ckh, curkey, 1); // or some alternate hash

        // Now the evicted item becomes what we're trying to insert
        argkey = curkey;
        argdata = curdata;
        bucket = alt_bucket;
    }

    // Failed after max iterations
    return true;

